/* 成员编号为 1..n，每人初始独立成组，孤立成员也要计数。 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
int mn(int a, int b)  {
    return a < b ? a : b;
}
int mx(int a, int b)  {
    return a > b ? a : b;
}
int read(void)  {
    int x = 0;
    if (scanf("%d", &x) != 1) return 0;
    return x;
}
int readstr(int* a)  {
    char s[20001];
    if (scanf("%20000s", s) != 1) return 0;
    if (strcmp(s, "-") == 0) return 0;
    int n = (int)strlen(s);
    for (int i = 0; i < n; i++) a[i] = (unsigned char)s[i];
    return n;
}
void emit(int x)  {
    printf("%d ", x);
}
void emitstr(int* a, int n)  {
    if (n == 0) putchar('-');
    for (int i = 0; i < n; i++) putchar(a[i]);
    putchar(' ');
}
int main(void)  {
    static int a[20000];
    static int b[20000];
    static int d[20000];
    static int e[20000];
    int ans = 0, i = 0, m = 0, n = 0, u = 0, v = 0;
    n = read();
    m = read();
    for (i = 0; i < (n + 1); i += 1)  {
        a[i] = i;
    }
    /* 沿父数组查找根；本参考程序没有路径压缩，只有不同根才连接。 */
    ans = n;
    for (i = 0; i < m; i += 1)  {
        u = read();
        v = read();
        while (a[u] != u)  {
            u = a[u];
        }
        while (a[v] != v)  {
            v = a[v];
        }
        if (u != v)  {
            a[u] = v;
            ans = (ans - 1);
        }
    }
    /* 每次真正合并两组才减少 ans，重复联系和自环不改变组数。 */
    emit(ans);
    return 0;
}

